<?php declare(strict_types=1); require_once __DIR__.'/../../config/db.php'; require_once __DIR__.'/../../lib/session.php'; require_once __DIR__.'/../../lib/auth.php'; use function App\Auth\{require_admin,csrf_token}; start_secure_session(); require_admin(); $pdo=db();$csrf=csrf_token();$mode=$pdo->query("SELECT setting_value FROM whatsapp_bridge_settings WHERE setting_key='intake_mode'")->fetchColumn()?:'manual';$rows=$pdo->query('SELECT * FROM whatsapp_ride_intakes ORDER BY id DESC LIMIT 100')->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><title>WhatsApp Intake Queue</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="/admin/index.php">← Admin</a><h1 class="h3 mt-3">WhatsApp intake queue</h1><p>Mode: <b id="mode"><?=$mode?></b> <button data-mode="manual" class="btn btn-sm btn-outline-primary">Manual review</button> <button data-mode="automatic" class="btn btn-sm btn-outline-success">Automatic</button></p><table class="table bg-white"><thead><tr><th>Message</th><th>Suggested ride</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars($r['raw_text'])?><br><small><?=htmlspecialchars($r['source_sender_jid'])?></small></td><td><?=htmlspecialchars((string)$r['ride_type'])?><br><?=htmlspecialchars((string)$r['from_text'])?> → <?=htmlspecialchars((string)$r['to_text'])?></td><td><?=$r['intake_status']?></td><td><?php if($r['intake_status']!=='posted'): ?><button class="btn btn-primary review" data-r='<?=htmlspecialchars(json_encode($r),ENT_QUOTES)?>'>Review</button><?php endif ?></td></tr><?php endforeach ?></tbody></table></main><div class="modal fade" id="m"><div class="modal-dialog"><form class="modal-content" id="f"><div class="modal-header"><h5>Review and send</h5></div><div class="modal-body"><input name="id" type="hidden"><select class="form-select mb-2" name="type"><option value="offer">Offering</option><option value="request">Looking</option></select><input class="form-control mb-2" name="from_text" placeholder="From"><input class="form-control mb-2" name="to_text" placeholder="To"><textarea class="form-control mb-2" name="note" placeholder="Note"></textarea><input class="form-control mb-2" name="phone" placeholder="Call number"><input class="form-control" name="whatsapp" placeholder="WhatsApp number"></div><div class="modal-footer"><button class="btn btn-success">Send to WhatsApp</button></div></form></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const csrf='<?=htmlspecialchars($csrf)?>',form=document.querySelector('#f'),modal=new bootstrap.Modal('#m');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{await fetch('/api/admin/whatsapp_intake_mode.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:b.dataset.mode,csrf})});location.reload()});document.querySelectorAll('.review').forEach(b=>b.onclick=()=>{let r=JSON.parse(b.dataset.r);for(let k in r)if(form.elements[k])form.elements[k].value=r[k]||'';modal.show()});form.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(form));d.csrf=csrf;let r=await fetch('/api/admin/whatsapp_intake_send.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),j=await r.json();if(j.ok)location.reload();else alert(j.error||'Send failed')};</script></body></html>
